def source(fmt):return next(s for s in sources if s['collection']=='settlement_and_reconciliation' and s['format']==fmt)
D,Q,W=source('docx'),source('pdf'),source('xlsx');DS,QS,WS=[s['source_id'] for s in [D,Q,W]]
